import React, { memo, useRef, useMemo, useState, useEffect } from 'react';
import {
  Background,
  Controls,
  Handle,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useEdgesState,
  useNodesState,
} from '@xyflow/react';
import useDiagramPlayback from '../../../hooks/useDiagramPlayback';
import { decorateFlowEdges } from '../../../utils/engineeringFlows';
import DiagramPlaybackControls from '../DiagramPlaybackControls';
import { engineeringEdgeTypes } from '../engineeringEdgeTypes';
import '@xyflow/react/dist/style.css';

const StepNode = memo(({ data }) => {
  return (
    <div
      style={{
        minWidth: 300,
        maxWidth: 300,
        padding: 18,
        borderRadius: 18,
        background: 'rgba(255,255,255,0.06)',
        border: '1px solid rgba(255,255,255,0.12)',
        color: '#fff',
        boxShadow: '0 10px 28px rgba(0,0,0,0.25)',
        backdropFilter: 'blur(10px)',
        textAlign: 'center',
      }}
    >
      <Handle type="target" position={Position.Top} style={{ opacity: 0 }} />
      <Handle type="source" position={Position.Bottom} style={{ opacity: 0 }} />
      <div style={{ fontSize: 12, opacity: 0.65, marginBottom: 8 }}>{data.kicker}</div>
      <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 8 }}>{data.label}</div>
      <div style={{ fontSize: 13, lineHeight: 1.45, opacity: 0.82 }}>{data.description}</div>
    </div>
  );
});

const nodeTypes = { stepNode: StepNode };

const initialNodes = [
  {
    id: 'a',
    type: 'stepNode',
    position: { x: 420, y: 60 },
    data: {
      kicker: 'Paso 1',
      label: 'Análisis de la página nativa',
      description: 'Se estudia la página base para entender su estructura, comportamiento y puntos de intervención.',
    },
    draggable: false,
  },
  {
    id: 'b',
    type: 'stepNode',
    position: { x: 420, y: 308 },
    data: {
      kicker: 'Paso 2',
      label: 'Identificación de patrones y restricciones',
      description: 'Se detectan reglas visuales, técnicas y limitaciones de integración.',
    },
    draggable: false,
  },
  {
    id: 'c',
    type: 'stepNode',
    position: { x: 420, y: 556 },
    data: {
      kicker: 'Paso 3',
      label: 'Construcción de contexto técnico',
      description: 'Se organiza la información necesaria para orientar la solución.',
    },
    draggable: false,
  },
  {
    id: 'd',
    type: 'stepNode',
    position: { x: 420, y: 804 },
    data: {
      kicker: 'Paso 4',
      label: 'Generación asistida por IA',
      description: 'Se genera una propuesta inicial apoyada por IA.',
    },
    draggable: false,
  },
  {
    id: 'e',
    type: 'stepNode',
    position: { x: 420, y: 1052 },
    data: {
      kicker: 'Paso 5',
      label: 'Ajuste y validación manual',
      description: 'Se refinan detalles y se valida la solución final.',
    },
    draggable: false,
  },
  {
    id: 'f',
    type: 'stepNode',
    position: { x: 420, y: 1300 },
    data: {
      kicker: 'Resultado',
      label: 'Personalización no invasiva lista para integrar',
      description: 'La solución queda preparada para integrarse sin alterar agresivamente la página original.',
    },
    draggable: false,
  },
];

const initialEdges = [
  {
    id: 'a-b',
    source: 'a',
    target: 'b',
    animated: true,
    type: 'smoothstep',
    style: { stroke: 'rgba(147,197,253,0.9)', strokeWidth: 3 },
  },
  {
    id: 'b-c',
    source: 'b',
    target: 'c',
    animated: true,
    type: 'smoothstep',
    style: { stroke: 'rgba(147,197,253,0.9)', strokeWidth: 3 },
  },
  {
    id: 'c-d',
    source: 'c',
    target: 'd',
    animated: true,
    type: 'smoothstep',
    style: { stroke: 'rgba(147,197,253,0.9)', strokeWidth: 3 },
  },
  {
    id: 'd-e',
    source: 'd',
    target: 'e',
    animated: true,
    type: 'smoothstep',
    style: { stroke: 'rgba(147,197,253,0.9)', strokeWidth: 3 },
  },
  {
    id: 'e-f',
    source: 'e',
    target: 'f',
    animated: true,
    type: 'smoothstep',
    style: { stroke: 'rgba(134,239,172,0.9)', strokeWidth: 3 },
  },
];

function SolutionFlowContent() {
  const frameRef = useRef(null);
  const playback = useDiagramPlayback(frameRef, 'methodology');
  const [nodes, , onNodesChange] = useNodesState(initialNodes);
  const [edges, , onEdgesChange] = useEdgesState(initialEdges);
  const animatedEdges = useMemo(() => decorateFlowEdges(edges, 'methodology', playback.step), [edges, playback.step]);
  const [isMobile, setIsMobile] = useState(() => typeof window !== 'undefined' && window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div className="diagram-scene">
      <DiagramPlaybackControls playback={playback} id="diagram-methodology-solution" title="Metodología: solución" />
    <div
      ref={frameRef} id="diagram-methodology-solution" tabIndex={-1} role="group" aria-label="Metodología: solución"
      data-playing={playback.playing}
      className="diagram-frame"
      style={{
        width: '100%',
        height: isMobile ? '650px' : 1180,
        background: 'radial-gradient(circle at top, rgba(255,255,255,0.06), transparent 24%), #05070b',
        borderRadius: 28,
        overflow: 'hidden',
        border: '1px solid rgba(255,255,255,0.08)',
        position: 'relative',
      }}
    >
      <div className="diagram-caption" style={{ position: 'absolute', zIndex: 10, padding: '24px 26px', pointerEvents: 'none' }}>
        <div style={{ color: '#fff', fontSize: 28, fontWeight: 700 }}>
          Flujo de personalización no invasiva
        </div>
        <div style={{ color: 'rgba(255,255,255,0.62)', marginTop: 8, maxWidth: 760, lineHeight: 1.45 }}>
          Desde el análisis inicial hasta una solución lista para integrar.
        </div>
      </div>
      <ReactFlow
        edgeTypes={engineeringEdgeTypes}
        id="rf-methodology-solution"
        key={isMobile ? 'mobile' : 'desktop'}
        nodes={nodes}
        edges={animatedEdges}
        nodeTypes={nodeTypes}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        fitView
        minZoom={0.1}
        fitViewOptions={{ padding: 0.2 }}
        nodesDraggable={false}
        nodesConnectable={false}
        elementsSelectable={false}
        zoomOnScroll={false}
        panOnDrag={false}
        preventScrolling={false}
        colorMode="dark"
      >
        <Background gap={28} size={1} color="rgba(255,255,255,0.07)" />
        <Controls showInteractive={false} />
      </ReactFlow>
    </div>
    </div>
  );
}

export default function MetodologiaSolutionFlow() {
  return (
    <ReactFlowProvider>
      <SolutionFlowContent />
    </ReactFlowProvider>
  );
}

import React, { memo, useRef, useMemo, useState, useEffect } from 'react';
import {
  Background,
  Controls,
  Handle,
  MiniMap,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useEdgesState,
  useNodesState,
} from '@xyflow/react';
import useDiagramPlayback from '../../../hooks/useDiagramPlayback';
import { decorateFlowEdges } from '../../../utils/engineeringFlows';
import DiagramPlaybackControls from '../DiagramPlaybackControls';
import { engineeringEdgeTypes } from '../engineeringEdgeTypes';
import '@xyflow/react/dist/style.css';

const glassCard = {
  background: 'rgba(255,255,255,0.05)',
  border: '1px solid rgba(255,255,255,0.10)',
  borderRadius: 22,
  color: '#fff',
  boxShadow: '0 12px 36px rgba(0,0,0,0.28)',
  backdropFilter: 'blur(10px)',
};

const zoneStyle = {
  background: 'rgba(255,255,255,0.03)',
  border: '1px solid rgba(255,255,255,0.08)',
  borderRadius: 28,
  color: '#fff',
  boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.05)',
};

const StepNode = memo(({ data }) => {
  return (
    <div
      style={{
        ...glassCard,
        width: data.width,
        minWidth: data.minWidth !== undefined ? data.minWidth : 240,
        padding: 18,
        boxShadow: data.active
          ? '0 0 0 1px rgba(147,197,253,0.45), 0 0 36px rgba(147,197,253,0.18)'
          : glassCard.boxShadow,
        border: data.active
          ? '1px solid rgba(147,197,253,0.38)'
          : '1px solid rgba(255,255,255,0.10)',
      }}
    >
      <Handle type="target" position={Position.Left} id="left" style={{ opacity: 0 }} />
      <Handle type="target" position={Position.Top} id="top" style={{ opacity: 0 }} />
      <div style={{ fontSize: 12, opacity: 0.62, marginBottom: 8 }}>{data.kicker}</div>
      <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 8 }}>{data.label}</div>
      <div style={{ fontSize: 13, lineHeight: 1.45, opacity: 0.78 }}>
        {data.description}
      </div>

      {data.badge && (
        <div
          style={{
            marginTop: 14,
            display: 'inline-flex',
            padding: '6px 10px',
            borderRadius: 999,
            fontSize: 12,
            background: 'rgba(255,255,255,0.08)',
            border: '1px solid rgba(255,255,255,0.08)',
          }}
        >
          {data.badge}
        </div>
      )}

      <Handle type="source" position={Position.Right} id="right" style={{ opacity: 0 }} />
      <Handle type="source" position={Position.Bottom} id="bottom" style={{ opacity: 0 }} />
    </div>
  );
});

const MonitorNode = memo(({ data }) => {
  return (
    <div
      style={{
        ...glassCard,
        minWidth: 220,
        padding: 16,
        border: `1px solid ${data.borderColor}`,
        boxShadow: `0 0 28px ${data.glow}`,
      }}
    >
      <Handle type="target" position={Position.Left} id="left" style={{ opacity: 0 }} />
      <Handle type="source" position={Position.Bottom} id="bottom" style={{ opacity: 0 }} />
      <div style={{ fontSize: 12, opacity: 0.62, marginBottom: 8 }}>Monitoreo</div>
      <div style={{ fontSize: 17, fontWeight: 700, marginBottom: 8 }}>{data.label}</div>
      <div style={{ fontSize: 13, lineHeight: 1.45, opacity: 0.78 }}>
        {data.description}
      </div>
    </div>
  );
});

const ZoneNode = memo(({ data }) => {
  return (
    <div
      style={{
        ...zoneStyle,
        width: data.width,
        height: data.height,
        padding: 18,
        pointerEvents: 'none',
      }}
    >
      <div style={{ fontSize: 13, opacity: 0.6, marginBottom: 8 }}>{data.kicker}</div>
      <div style={{ fontSize: 20, fontWeight: 700 }}>{data.label}</div>
      <div style={{ fontSize: 13, opacity: 0.72, marginTop: 6, maxWidth: 360 }}>
        {data.description}
      </div>
    </div>
  );
});

const NoteNode = memo(() => {
  return (
    <div
      style={{
        ...glassCard,
        minWidth: 330,
        padding: 18,
        border: '1px solid rgba(253,224,71,0.18)',
        boxShadow: '0 0 30px rgba(253,224,71,0.08)',
      }}
    >
      <div style={{ fontSize: 12, opacity: 0.62, marginBottom: 8 }}>Lectura del diagrama</div>
      <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 10 }}>
        Secuencial en negocio, paralelo en observabilidad
      </div>
      <div style={{ fontSize: 13, lineHeight: 1.5, opacity: 0.8 }}>
        El negocio avanza paso a paso desde la web hasta RADIUS. La observabilidad, en cambio,
        sigue ambos dominios al mismo tiempo mediante dos grupos independientes.
      </div>
    </div>
  );
});

const nodeTypes = {
  stepNode: StepNode,
  monitorNode: MonitorNode,
  zoneNode: ZoneNode,
  noteNode: NoteNode,
};

const initialNodes = [
  // ZONAS
  {
    id: 'zone-web',
    type: 'zoneNode',
    position: { x: 0, y: 420 },
    data: {
      kicker: 'Dominio 1',
      label: 'Capa Web',
      description: 'Aquí inicia la interacción del usuario y se valida que la navegación/servicio concluyan correctamente.',
      width: 620,
      height: 800,
    },
    draggable: false,
    selectable: false,
  },
  {
    id: 'zone-radius',
    type: 'zoneNode',
    position: { x: 830, y: 420 },
    data: {
      kicker: 'Dominio 2',
      label: 'Capa RADIUS',
      description: 'Posteriormente se genera la solicitud hacia RADIUS y se confirma la autenticación.',
      width: 620,
      height: 800,
    },
    draggable: false,
    selectable: false,
  },

  // FLUJO NEGOCIO
  {
    id: 'user-request',
    type: 'stepNode',
    position: { x: 168, y: 710 },
    data: {
      kicker: 'Inicio',
      label: 'Petición web del usuario',
      description: 'El usuario inicia la interacción por medio de la navegación o del servicio web.',
      badge: 'Paso 1',
      active: true,
      width: 350,
      minWidth: 350,
    },
    draggable: false,
  },
  {
    id: 'web-ok',
    type: 'stepNode',
    position: { x: 168, y: 1010 },
    data: {
      kicker: 'Validación web',
      label: 'Navegación / servicio web correcto',
      description: 'Solo si la operación web concluye correctamente, el flujo continúa hacia autenticación.',
      badge: 'Paso 2',
      active: true,
      width: 350,
      minWidth: 350,
    },
    draggable: false,
  },
  {
    id: 'radius-request',
    type: 'stepNode',
    position: { x: 968, y: 710 },
    data: {
      kicker: 'Autenticación',
      label: 'Solicitud a RADIUS',
      description: 'Después del éxito en la capa web, se dispara la solicitud de autenticación a RADIUS.',
      badge: 'Paso 3',
      active: true,
      width: 350,
      minWidth: 350,
    },
    draggable: false,
  },
  {
    id: 'radius-ok',
    type: 'stepNode',
    position: { x: 968, y: 1010 },
    data: {
      kicker: 'Confirmación',
      label: 'Autenticación confirmada',
      description: 'RADIUS confirma la autenticación y se cierra el flujo operativo de negocio.',
      badge: 'Paso 4',
      active: true,
      width: 350,
      minWidth: 350,
    },
    draggable: false,
  },

  // MONITOREO PARALELO
  {
    id: 'monitor-web',
    type: 'monitorNode',
    position: { x: 170, y: 550 },
    data: {
      label: 'Grupo de monitoreo Web',
      description: 'Observa el dominio web sin depender del grupo RADIUS.',
      borderColor: 'rgba(125,211,252,0.30)',
      glow: 'rgba(125,211,252,0.10)',
    },
    draggable: false,
  },
  {
    id: 'monitor-radius',
    type: 'monitorNode',
    position: { x: 930, y: 550 },
    data: {
      label: 'Grupo de monitoreo RADIUS',
      description: 'Observa autenticación en paralelo, con independencia del grupo web.',
      borderColor: 'rgba(196,181,253,0.30)',
      glow: 'rgba(196,181,253,0.10)',
    },
    draggable: false,
  },

  // NOTA
  {
    id: 'note',
    type: 'noteNode',
    position: { x: 260, y: 1300 },
    data: {},
    draggable: false,
  },
];

const initialEdges = [
  // Flujo secuencial de negocio
  {
    id: 'e1',
    source: 'user-request',
    target: 'web-ok',
    sourceHandle: 'bottom',
    targetHandle: 'top',
    type: 'smoothstep',
    animated: true,
    label: '1. interacción web',
    labelStyle: { fill: '#cbd5e1', fontSize: 12 },
    style: {
      stroke: 'rgba(147,197,253,0.9)',
      strokeWidth: 3,
    },
  },
  {
    id: 'e2',
    source: 'web-ok',
    target: 'radius-request',
    sourceHandle: 'right',
    targetHandle: 'left',
    type: 'smoothstep',
    animated: true,
    label: '2. si web termina bien → RADIUS',
    labelStyle: { fill: '#cbd5e1', fontSize: 12 },
    style: {
      stroke: 'rgba(147,197,253,0.9)',
      strokeWidth: 3,
    },
  },
  {
    id: 'e3',
    source: 'radius-request',
    target: 'radius-ok',
    sourceHandle: 'bottom',
    targetHandle: 'top',
    type: 'smoothstep',
    animated: true,
    label: '3. autenticación confirmada',
    labelStyle: { fill: '#cbd5e1', fontSize: 12 },
    style: {
      stroke: 'rgba(147,197,253,0.9)',
      strokeWidth: 3,
    },
  },

  // Monitoreo paralelo e independiente
  {
    id: 'm1',
    source: 'monitor-web',
    target: 'user-request',
    sourceHandle: 'bottom',
    targetHandle: 'top',
    type: 'smoothstep',
    animated: true,
    style: {
      stroke: 'rgba(125,211,252,0.8)',
      strokeWidth: 2,
      strokeDasharray: '8 8',
    },
  },
  {
    id: 'm2',
    source: 'monitor-radius',
    target: 'radius-request',
    sourceHandle: 'bottom',
    targetHandle: 'top',
    type: 'smoothstep',
    animated: true,
    style: {
      stroke: 'rgba(196,181,253,0.85)',
      strokeWidth: 2,
      strokeDasharray: '8 8',
    },
  },
];

function ParallelMonitoringDiagram() {
  const frameRef = useRef(null);
  const playback = useDiagramPlayback(frameRef, 'business');
  const [nodes, , onNodesChange] = useNodesState(initialNodes);
  const [edges, , onEdgesChange] = useEdgesState(initialEdges);
  const animatedEdges = useMemo(() => decorateFlowEdges(edges, 'business', playback.step), [edges, playback.step]);
  const [isMobile, setIsMobile] = useState(() => typeof window !== 'undefined' && window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const defaultEdgeOptions = useMemo(
    () => ({
      type: 'smoothstep',
    }),
    []
  );

  return (
    <div className="diagram-scene">
      <DiagramPlaybackControls playback={playback} id="diagram-business" title="Flujo secuencial y monitoreo paralelo" />
    <div
      ref={frameRef} id="diagram-business" tabIndex={-1} role="group" aria-label="Flujo secuencial y monitoreo paralelo"
      data-playing={playback.playing}
      className="diagram-frame"
      style={{
        width: '100%',
        position: 'relative',
        height: isMobile ? '550px' : 660,
        background:
          'radial-gradient(circle at top, rgba(255,255,255,0.06), transparent 24%), #05070b',
        borderRadius: 28,
        overflow: 'hidden',
        border: '1px solid rgba(255,255,255,0.08)',
      }}
    >
      <div
        className="diagram-caption"
        style={{
          position: 'absolute',
          zIndex: 10,
          padding: '24px 26px',
          pointerEvents: 'none',
        }}
      >
        <div style={{ color: '#fff', fontSize: 28, fontWeight: 700 }}>
          Flujo secuencial + monitoreo paralelo
        </div>
        <div
          style={{
            color: 'rgba(255,255,255,0.62)',
            marginTop: 8,
            maxWidth: 860,
            lineHeight: 1.45,
          }}
        >
          El negocio avanza primero por la capa web y después hacia RADIUS. La solución observa
          ambos dominios al mismo tiempo, manteniendo independencia entre el grupo web y el grupo RADIUS.
        </div>
      </div>

      <ReactFlow
        edgeTypes={engineeringEdgeTypes}
        id="rf-business"
        key={isMobile ? 'mobile' : 'desktop'}
        nodes={nodes}
        edges={animatedEdges}
        nodeTypes={nodeTypes}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        defaultEdgeOptions={defaultEdgeOptions}
        fitView
        fitViewOptions={{ padding: 0.05 }}
        nodesDraggable={false}
        nodesConnectable={false}
        elementsSelectable={false}
        zoomOnScroll={false}
        preventScrolling={false}
        panOnDrag={!isMobile}
        minZoom={isMobile ? 0.05 : 0.35}
        maxZoom={1.5}
        colorMode="dark"
      >
        <Background gap={24} size={1} color="rgba(255,255,255,0.07)" />
        <Controls showInteractive={false} />
        {/* <MiniMap
          pannable
          zoomable
          style={{
            background: 'rgba(255,255,255,0.04)',
            border: '1px solid rgba(255,255,255,0.08)',
          }}
          nodeColor={(node) => {
            if (node.id.startsWith('monitor')) return 'rgba(196,181,253,0.9)';
            if (node.id.startsWith('zone')) return 'rgba(255,255,255,0.18)';
            return 'rgba(147,197,253,0.9)';
          }}
        /> */}
        </ReactFlow>
    </div>
    </div>
  );
}

export default function App() {
  return (
    <ReactFlowProvider>
      <ParallelMonitoringDiagram />
    </ReactFlowProvider>
  );
}

import React, { memo, useRef, useEffect, useMemo, useState } from 'react';
import {
  Background,
  Controls,
  Handle,
  MiniMap,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useEdgesState,
  useNodesState,
} from '@xyflow/react';
import useDiagramPlayback from '../../../hooks/useDiagramPlayback';
import { decorateFlowEdges } from '../../../utils/engineeringFlows';
import DiagramPlaybackControls from '../DiagramPlaybackControls';
import { engineeringEdgeTypes } from '../engineeringEdgeTypes';
import '@xyflow/react/dist/style.css';

const CARD_BASE = {
  background: 'rgba(255,255,255,0.06)',
  color: '#fff',
  border: '1px solid rgba(255,255,255,0.12)',
  borderRadius: 22,
  boxShadow: '0 10px 30px rgba(0,0,0,0.25)',
  backdropFilter: 'blur(12px)',
};

const ServiceNode = memo(({ data }) => {
  const activeGlow = data.active
    ? '0 0 0 1px rgba(164, 202, 254, 0.55), 0 0 36px rgba(164, 202, 254, 0.20)'
    : '0 10px 30px rgba(0,0,0,0.25)';

  return (
    <div
      style={{
        ...CARD_BASE,
        minWidth: 220,
        padding: 18,
        boxShadow: activeGlow,
        border: data.active
          ? '1px solid rgba(164, 202, 254, 0.45)'
          : '1px solid rgba(255,255,255,0.12)',
      }}
    >
      <Handle
        type="target"
        position={Position.Left}
        style={{ opacity: 0, width: 8, height: 8 }}
      />

      <div style={{ fontSize: 15, opacity: 0.7, marginBottom: 8 }}>{data.kicker}</div>
      <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 8 }}>{data.label}</div>
      <div style={{ fontSize: 13, lineHeight: 1.45, opacity: 0.75 }}>{data.description}</div>

      {data.badge && (
        <div
          style={{
            marginTop: 14,
            display: 'inline-flex',
            padding: '6px 10px',
            borderRadius: 999,
            fontSize: 12,
            background: data.active
              ? 'rgba(164, 202, 254, 0.18)'
              : 'rgba(255,255,255,0.08)',
            border: '1px solid rgba(255,255,255,0.10)',
          }}
