function LoadBalancerTraceabilityDiagram() {
  const frameRef = useRef(null);
  const playback = useDiagramPlayback(frameRef, 'balance', 1);
  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);
  const activeServerIndex = playback.step;
  const animatedEdges = useMemo(() => decorateFlowEdges(edges, 'balance', playback.step), [edges, playback.step]);
  const [isMobile, setIsMobile] = useState(() => typeof window !== 'undefined' && window.innerWidth <= 768);

  const serverIds = useMemo(() => ['ws1', 'ws2', 'ws3'], []);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    const activeId = serverIds[activeServerIndex];

    setNodes((current) =>
      current.map((node) => {
        if (!serverIds.includes(node.id)) return node;

        return {
          ...node,
          data: {
            ...node.data,
            active: node.id === activeId,
            badge: node.id === activeId ? 'Procesando solicitud' : 'Misma función',
          },
        };
      })
    );

    setEdges((current) =>
      current.map((edge) => {
        const isActive = edge.id === `lb-${activeId}`;

        if (edge.source === 'lb' && edge.target.startsWith('ws')) {
          return {
            ...edge,
            animated: isActive,
            style: {
              stroke: isActive
                ? 'rgba(164, 202, 254, 0.85)'
                : 'rgba(255,255,255,0.18)',
              strokeWidth: isActive ? 3 : 2,
            },
          };
        }

        return edge;
      })
    );
  }, [activeServerIndex, serverIds, setEdges, setNodes]);

  return (
    <div className="diagram-scene">
      <DiagramPlaybackControls playback={playback} id="diagram-loadbalance" title="Trazabilidad en arquitectura horizontal" simulation />
    <div
      ref={frameRef} id="diagram-loadbalance" tabIndex={-1} role="group" aria-label="Trazabilidad en arquitectura horizontal"
      data-playing={playback.playing}
      className="diagram-frame diagram-player"
      style={{
        width: '100%',
        position: 'relative',
        height: isMobile ? '550px' : '760px',
        background:
          'radial-gradient(circle at top, rgba(255,255,255,0.06), transparent 25%), #05070b',
        borderRadius: 28,
        overflow: 'hidden',
        border: '1px solid rgba(255,255,255,0.08)',
      }}
    >
      <div
        className="diagram-caption"
        style={{
          position: 'absolute',
          zIndex: 10,
          padding: '24px 28px',
          pointerEvents: 'none',
        }}
      >
        <div style={{ color: '#fff', fontSize: 28, fontWeight: 700 }}>
          Trazabilidad en arquitectura horizontal
        </div>
        <div style={{ color: 'rgba(255,255,255,0.62)', marginTop: 8, maxWidth: 700 }}>
          Varios servidores web cumplen la misma función. El balanceador decide a cuál
          enviar la petición, lo que dificulta saber dónde buscar una MAC específica.
        </div>
      </div>

      <ReactFlow
        edgeTypes={engineeringEdgeTypes}
        id="rf-loadbalance"
        key={isMobile ? 'mobile' : 'desktop'}
          nodes={nodes}
          edges={animatedEdges}
          nodeTypes={nodeTypes}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          fitView
          fitViewOptions={{ padding: 0.05 }}
          nodesDraggable={false}
          nodesConnectable={false}
          elementsSelectable={false}
          zoomOnScroll={false}
          preventScrolling={false}
          panOnDrag={false}
          minZoom={isMobile ? 0.05 : 0.2}
          colorMode="dark"
          defaultEdgeOptions={{
            type: 'smoothstep',
          }}
        >
          <Background
            gap={24}
            size={1}
            color="rgba(255,255,255,0.08)"
          />
          <Controls showInteractive={false} />
          {/* <MiniMap
            pannable
            zoomable
            style={{
              background: 'rgba(255,255,255,0.04)',
              border: '1px solid rgba(255,255,255,0.08)',
            }}
            nodeColor={() => 'rgba(255,255,255,0.45)'}
          /> */}
        </ReactFlow>
    </div>
    </div>
  );
}

export default function App() {
  return (
    <ReactFlowProvider>
      <LoadBalancerTraceabilityDiagram />
    </ReactFlowProvider>
  );
}

